    "tenantInvitation.store": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** Format: email */
                    email: string;
                    company_name?: string | null;
                    /**
                     * @description Por qué VERTICAL entra el cliente (13.16). Solo un desarrollador
                     *     tiene verticales; se comprueba contra las suyas más abajo.
                     */
                    vertical?: string | null;
                    /**
                     * @description `despacho|cliente` es el vocabulario de la gestoría; `sponsor|self`
                     *     el general del modelo de facturación (Tenant::BILLING_*). Se
                     *     aceptan los dos y se guarda el de siempre, para no partir la
                     *     columna ni el asistente en dos.
                     * @enum {string}
                     */
                    billing?: "despacho" | "cliente" | "sponsor" | "self";
                };
            };
        };
        responses: {
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        message: string;
                        data: {
                            id: string;
                            email: string;
                            company_name: string;
                            billing: string;
                            status: string;
                            expires_at: string;
                            accepted_tenant_id: string;
                            accepted_at: string;
                            created_at: string;
                        };
                    };
                };
            };
            401: components["responses"]["AuthenticationException"];
            /** @description An error */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @constant */
                        error: "invitation_quota_exceeded";
                        message: string;
                    } | {
                        /**
                         * @description Error overview.
                         * @example Solo las gestorías y los desarrolladores pueden enviar invitaciones a clientes.
                         */
                        message: string;
                    };
                };
            };
            422: components["responses"]["ValidationException"];
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @constant */
                        message: "No se pudo enviar el email de invitación. Revisa la configuración de correo e inténtalo de nuevo.";
                    } | {
                        /** @constant */
                        error: "integrator_mail_failed";
                        /** @constant */
                        code: "integrator_mail_failed";
                        /** @constant */
                        message: "No se pudo enviar la invitación desde tu cuenta de correo. Revisa la configuración de tu correo e inténtalo de nuevo; no se ha enviado desde Pimia.";
                    };
                };
            };
        };
    };
